def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text according to the specified dialect."""
    import re

    lines = text.splitlines()
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None

    # State for building a multi-line value
    building = False
    building_key: str | None = None
    building_parts: list[str] = []

    def finalize_building() -> None:
        """Store the accumulated value for the current key."""
        nonlocal building, building_key, building_parts, current_section, sections
        if building:
            if current_section is None:
                raise ValueError("Key line before any section header")
            sections.setdefault(current_section, {})[building_key] = "\n".join(building_parts)
            building = False
            building_key = None
            building_parts = []

    def parse_value(v: str) -> str:
        """Parse a raw value string according to quoting and comment rules."""
        in_quote = False
        i = 0
        L = len(v)
        while i < L:
            ch = v[i]
            if ch == '"':
                in_quote = not in_quote
                i += 1
            elif not in_quote and i + 1 < L and v[i] in " \t" and v[i + 1] in ";#":
                # start of an inline comment
                return v[:i]
            else:
                i += 1
        commentless = v
        stripped = commentless.strip()
        if len(stripped) >= 2 and stripped[0] == '"' and stripped[-1] == '"':
            # quoted value – keep interior exactly, remove the quotes
            return stripped[1:-1]
        else:
            # unquoted value – strip surrounding whitespace
            return commentless.strip()

    idx = 0
    while idx < len(lines):
        line = lines[idx]
        stripped = line.lstrip()

        # 1. Empty line or comment line
        if not stripped or stripped[0] in ";#":
            if building:
                finalize_building()
            idx += 1
            continue

        # 2. Section header
        if stripped.startswith("["):
            if building:
                finalize_building()
            bracket_end = stripped.find("]", 1)
            if bracket_end == -1:
                raise ValueError(f"Malformed section header: {line}")
            name = stripped[1:bracket_end].strip()
            remainder = stripped[bracket_end + 1 :]
            # Remove possible inline comment (outside quotes) from the remainder
            comment_pos = None
            for marker in (" ;", " #"):
                pos = remainder.find(marker)
                if pos != -1:
                    if comment_pos is None or pos < comment_pos:
                        comment_pos = pos
            if comment_pos is not None:
                remainder = remainder[:comment_pos]
            if remainder.strip():
                raise ValueError(f"Extra text after section header: {line}")
            current_section = name
            sections.setdefault(current_section, {})
            idx += 1
            continue

        # 3. Continuation line (only if we are currently building a value)
        if building and line and line[0] in " \t":
            building_parts.append(line.strip())
            idx += 1
            continue

        # 4. Key line
        if building:
            finalize_building()

        eq_pos = line.find("=")
        colon_pos = line.find(":")
        delim_pos = -1
        if eq_pos != -1 and colon_pos != -1:
            delim_pos = min(eq_pos, colon_pos)
        elif eq_pos != -1:
            delim_pos = eq_pos
        elif colon_pos != -1:
            delim_pos = colon_pos
        else:
            raise ValueError(f"Malformed key line (no delimiter): {line}")

        key_raw = line[:delim_pos]
        value_raw = line[delim_pos + 1 :]
        key = key_raw.strip().lower()

        value = parse_value(value_raw)

        building_key = key
        building_parts = [value]
        building = True
        idx += 1
        continue

    # Finalise any pending value after the loop
    if building:
        finalize_building()

    # The DEFAULT section is special: its keys are inherited but not returned
    default_dict = sections.pop("DEFAULT", {})

    # ------------------------------------------------------------------
    # Interpolation resolution (recursive, with cycle detection)
    # ------------------------------------------------------------------
    pattern = re.compile(r"\$\{([^}]+)\}")

    def get_raw(sec: str, key: str) -> str:
        """Fetch the raw (uninterpolated) value for a key, falling back to DEFAULT."""
        if sec in sections and key in sections[sec]:
            return sections[sec][key]
        if key in default_dict:
            return default_dict[key]
        raise KeyError(f"Key {key!r} not found in section {sec!r} or DEFAULT")

    resolved: dict[tuple[str, str], str] = {}

    def resolve(sec: str, key: str, visited: set[tuple[str, str]]) -> str:
        """Return the fully interpolated value for (sec, key)."""
        if (sec, key) in visited:
            raise ValueError(f"Interpolation cycle detected involving {sec!r}:{key!r}")
        if (sec, key) in resolved:
            return resolved[(sec, key)]

        raw = get_raw(sec, key)

        def repl(m: re.Match) -> str:
            inner = m.group(1)
            if ":" in inner:
                sec_name, subkey = inner.split(":", 1)
                sec_name = sec_name.strip()
                subkey = subkey.strip().lower()
            else:
                sec_name = sec
                subkey = inner.strip().lower()
            return resolve(sec_name, subkey, visited | {(sec, key)})

        result = raw
        while True:
            m = pattern.search(result)
            if not m:
                break
            replacement = repl(m)
            result = result[:m.start()] + replacement + result[m.end():]

        resolved[(sec, key)] = result
        return result

    output: dict[str, dict[str, str]] = {}
    for sec_name, sec_dict in sections.items():
        if sec_name == "DEFAULT":
            continue
        final_dict: dict[str, str] = {}
        for key in sec_dict:
            final_dict[key] = resolve(sec_name, key, set())
        output[sec_name] = final_dict

    return output
