import unicodedata
import re

def slugify(title: str, max_len: int = 50) -> str:
    # 1. Transliterate to ASCII, dropping any remaining non‑ASCII characters
    ascii_title = unicodedata.normalize('NFKD', title).encode('ascii', 'ignore').decode('ascii')
    # 2. Lowercase
    ascii_title = ascii_title.lower()
    # 3. Replace runs of non‑a-z0-9 with a single hyphen and strip leading/trailing hyphens
    slug = re.sub(r'[^a-z0-9]+', '-', ascii_title).strip('-')
    # 4. Truncate if needed, respecting word boundaries
    if len(slug) <= max_len:
        return slug
    words = slug.split('-')
    result = ''
    for w in words:
        candidate = w if not result else f'{result}-{w}'
        if len(candidate) <= max_len:
            result = candidate
        else:
            break
    if result:
        return result.rstrip('-')
    # first word exceeds max_len – hard cut
    return slug[:max_len].rstrip('-')
