def summarize_ranges(nums: list[int]) -> str:
    """Return a compact string representation of sorted unique integers.
    Consecutive runs of length >=3 are shown as "start..end";
    shorter runs are listed individually, joined by commas without spaces.
    """
    if not nums:
        return ""

    # Sort and deduplicate
    uniq = sorted(set(nums))
    parts = []
    i = 0
    n = len(uniq)

    while i < n:
        start = uniq[i]
        j = i
        # Extend while the next number is consecutive
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        end = uniq[j]

        # Determine formatting based on run length
        if j - i + 1 >= 3:
            parts.append(f"{start}..{end}")
        else:
            for k in range(i, j + 1):
                parts.append(str(uniq[k]))

        i = j + 1

    return ",".join(parts)
